DROP FUNCTION IF EXISTS create_department(text, text);
CREATE FUNCTION create_department(p_name text, p_description text) RETURNS departments LANGUAGE sql AS $$ INSERT INTO departments (name, description) VALUES (p_name, p_description) RETURNING *; $$;
DROP FUNCTION IF EXISTS get_department(uuid);
CREATE FUNCTION get_department(p_id uuid) RETURNS SETOF departments LANGUAGE sql AS $$ SELECT * FROM departments WHERE id = p_id; $$;
DROP FUNCTION IF EXISTS update_department(uuid, text, text);
CREATE FUNCTION update_department(p_id uuid, p_name text, p_description text) RETURNS departments LANGUAGE plpgsql AS $$ DECLARE r departments; BEGIN UPDATE departments SET name = p_name, description = p_description WHERE id = p_id RETURNING * INTO r; IF NOT FOUND THEN RAISE EXCEPTION 'department % not found', p_id USING ERRCODE = 'P0002'; END IF; RETURN r; END $$;
DROP FUNCTION IF EXISTS delete_department(uuid);
CREATE FUNCTION delete_department(p_id uuid) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN DELETE FROM departments WHERE id = p_id; RETURN FOUND; END $$;
DROP FUNCTION IF EXISTS list_departments();
CREATE FUNCTION list_departments() RETURNS SETOF departments LANGUAGE sql AS $$ SELECT * FROM departments ORDER BY id; $$;
DROP FUNCTION IF EXISTS create_user(text, text, text, text, timestamptz);
CREATE FUNCTION create_user(p_email text, p_password_hash text, p_full_name text, p_role text, p_created_at timestamptz) RETURNS users LANGUAGE sql AS $$ INSERT INTO users (email, password_hash, full_name, role, created_at) VALUES (p_email, p_password_hash, p_full_name, p_role, p_created_at) RETURNING *; $$;
