CREATE FUNCTION update_user(p_id uuid, p_email text, p_password_hash text, p_full_name text, p_role text, p_created_at timestamptz) RETURNS users LANGUAGE plpgsql AS $$ DECLARE r users; BEGIN UPDATE users SET email = p_email, password_hash = p_password_hash, full_name = p_full_name, role = p_role, created_at = p_created_at WHERE id = p_id RETURNING * INTO r; IF NOT FOUND THEN RAISE EXCEPTION 'user % not found', p_id USING ERRCODE = 'P0002'; END IF; RETURN r; END $$;
DROP FUNCTION IF EXISTS delete_user(uuid);
CREATE FUNCTION delete_user(p_id uuid) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN DELETE FROM users WHERE id = p_id; RETURN FOUND; END $$;
DROP FUNCTION IF EXISTS list_users();
CREATE FUNCTION list_users() RETURNS SETOF users LANGUAGE sql AS $$ SELECT * FROM users ORDER BY id; $$;
