CREATE FUNCTION create_task(p_title text, p_description text, p_status text, p_due_date date, p_project_id uuid, p_assignee_id uuid) RETURNS tasks LANGUAGE sql AS $$ INSERT INTO tasks (title, description, status, due_date, project_id, assignee_id) VALUES (p_title, p_description, p_status, p_due_date, p_project_id, p_assignee_id) RETURNING *; $$;
